ci.run:
node -e '
  const needs = JSON.parse(process.env.NEEDS);
  const names = Object.keys(needs);
  for (const name of names) console.log(name + ": " + needs[name].result);
  const failed = names.filter((name) => needs[name].result !== "success");
  if (names.length === 0 || failed.length > 0) {
    console.error("not passed: " + (failed.join(", ") || "no jobs at all"));
    process.exit(1);
  }
'
